"""Invoice totals in yen. Each line is (unit_price, quantity). Consumption tax is 10%."""

from decimal import Decimal, ROUND_HALF_UP

TAX_RATE = Decimal("0.10")


def line_total(unit_price, quantity):
    return unit_price * quantity


def subtotal(lines):
    return sum(line_total(p, q) for p, q in lines)


def tax(lines):
    # tax is rounded once on the invoice subtotal, not per line
    return int((subtotal(lines) * TAX_RATE).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def total_with_tax(lines):
    return subtotal(lines) + tax(lines)
